// src/lib/plattform/backend/anlagen.js
//
// Backend-Teil „Anlagen & Monitoring“ (Stammdaten und Prozesse; eigene Schnittstelle, backend/index.js bleibt
// unverändert). Gleiche Auswahl wie backend(): Frappe bei PLATTFORM_BACKEND=frappe, sonst Demo (503 im
// Produktions-Build ohne PLATTFORM_DEMO=1). Messdaten (Zeitreihen) liefert src/lib/plattform/messdaten.
//
// Operationen (n = angemeldeter Nutzer), Vertrag: docs/API.md Abschnitt 10:
//   Anlagen:    anlagen(n,{q,typ,status}) · anlage(n,id) · anlagenKunden(n) · anlageAnlegen(n,daten) · anlageAendern(n,id,daten)
//   Einträge:   anlageEintragSpeichern(n,anlageId,{art,id?,daten}) · anlageEintragLoeschen(n,anlageId,{art,id})
//               (art: komponente | messpunkt | wartung | vertrag | monatswert)
//   Zähler:     zaehlerMonatswerte(n,anlageId)
//   Geräte:     geraetZugangAnlegen(n,anlageId,{bezeichnung}) → {zugang, passwort (einmalig), broker}
//               geraetZugang(n,id) · geraetZugangAktion(n,id,{aktion: sperren|entsperren|neu|testnachricht})
//   Störungen:  stoerungen(n,{anlageId,status,limit}) · stoerungAnlegen(n,{anlageId,schwere,titel,text})
//               stoerungAktion(n,id,{aktion: kommentar|quittieren|status|zuweisen|schwere, …}) · anlagenLeitstand(n)
//   Nur Demo:   stoerungSystem(befund) – nachgebildete Regeln des Ingest-Dienstes (Frappe: no-op, der Dienst meldet selbst)
//
// Nur serverseitig verwenden.

import * as demo from "./demo/anlagen";
import * as frappe from "./frappe/anlagen";
import { backendName, KONFIG_FEHLER } from "./index";
import { PlattformFehler } from "../fehler";

export const ANLAGEN_OPERATIONEN = [
  "anlagen", "anlage", "anlagenKunden", "anlageAnlegen", "anlageAendern", "anlageEintragSpeichern", "anlageEintragLoeschen", "zaehlerMonatswerte",
  "geraetZugangAnlegen", "geraetZugang", "geraetZugangAktion", "stoerungen", "stoerungAnlegen", "stoerungAktion", "anlagenLeitstand", "stoerungSystem",
];

if (process.env.NODE_ENV !== "production") {
  for (const [name, impl] of [["demo", demo], ["frappe", frappe]]) {
    const fehlt = ANLAGEN_OPERATIONEN.filter((op) => typeof impl[op] !== "function");
    if (fehlt.length) console.warn(`[plattform] Anlagen ${name}: fehlende Operationen ${fehlt.join(", ")}`);
  }
}

export function anlagenBackend() {
  const n = backendName();
  if (n === "frappe") return frappe;
  if (n === "demo") return demo;
  throw new PlattformFehler(503, KONFIG_FEHLER);
}
// src/lib/plattform/backend/frappe/anlagen.js
//
// Frappe-Adapter „Anlagen & Monitoring“. Methoden in oekoinvest_app.plattform.api.anlagen – Vertrag: docs/API.md,
// Abschnitt 10. Signaturen identisch zu backend/demo/anlagen.js. Frappe prüft Rolle UND Eigentum selbst.

import { METHODEN, frappeAufruf as aufruf } from "../frappe";

Object.assign(METHODEN, {
  anlagen: "anlagen.liste",
  anlage: "anlagen.holen",
  anlagenKunden: "anlagen.kunden",
  anlageAnlegen: "anlagen.anlegen",
  anlageAendern: "anlagen.aendern",
  anlageEintragSpeichern: "anlagen.eintrag_speichern",
  anlageEintragLoeschen: "anlagen.eintrag_loeschen",
  zaehlerMonatswerte: "anlagen.monatswerte",
  geraetZugangAnlegen: "anlagen.geraet_anlegen",
  geraetZugang: "anlagen.geraet",
  geraetZugangAktion: "anlagen.geraet_aktion",
  stoerungen: "anlagen.stoerungen",
  stoerungAnlegen: "anlagen.stoerung_anlegen",
  stoerungAktion: "anlagen.stoerung_aktion",
  anlagenLeitstand: "anlagen.leitstand",
});

export const anlagen = (n, filter = {}) => aufruf("anlagen", filter, n);
export const anlage = (n, id) => aufruf("anlage", { id }, n);
export const anlagenKunden = (n) => aufruf("anlagenKunden", {}, n);
export const anlageAnlegen = (n, daten = {}) => aufruf("anlageAnlegen", { daten }, n);
export const anlageAendern = (n, id, daten = {}) => aufruf("anlageAendern", { id, daten }, n);
export const anlageEintragSpeichern = (n, anlageId, { art, id = null, daten = {} } = {}) => aufruf("anlageEintragSpeichern", { anlageId, art, id, daten }, n);
export const anlageEintragLoeschen = (n, anlageId, { art, id } = {}) => aufruf("anlageEintragLoeschen", { anlageId, art, id }, n);
export const zaehlerMonatswerte = (n, anlageId) => aufruf("zaehlerMonatswerte", { anlageId }, n);
export const geraetZugangAnlegen = (n, anlageId, { bezeichnung = "" } = {}) => aufruf("geraetZugangAnlegen", { anlageId, bezeichnung }, n);
export const geraetZugang = (n, id) => aufruf("geraetZugang", { id }, n);
export const geraetZugangAktion = (n, id, daten = {}) => aufruf("geraetZugangAktion", { id, daten }, n);
export const stoerungen = (n, filter = {}) => aufruf("stoerungen", filter, n);
export const stoerungAnlegen = (n, daten = {}) => aufruf("stoerungAnlegen", { daten }, n);
export const stoerungAktion = (n, id, daten = {}) => aufruf("stoerungAktion", { id, daten }, n);
export const anlagenLeitstand = (n) => aufruf("anlagenLeitstand", {}, n);
/** Im Betrieb meldet der Ingest-Dienst Störungen direkt an Frappe (anlagen.dienst_stoerung) */
export const stoerungSystem = async () => null;
// src/lib/plattform/backend/kyc.js
//
// Backend-Teil „KYC/KYB – Identitäts- und Firmenprüfung“ (eigene Schnittstelle, backend/index.js bleibt unverändert).
// Gleiche Auswahl wie backend(): Frappe bei PLATTFORM_BACKEND=frappe, sonst Demo (503 im Produktions-Build ohne PLATTFORM_DEMO=1).
//
// Operationen (n = angemeldeter Nutzer), Vertrag: docs/API.md Abschnitt 11:
//   Nutzer:      kycFall(n) · kycSpeichern(n,{abschnitt,daten}) · kycDokumentSpeichern(n,{art,flaecheId,personId,ausgestelltAm,name,mime,daten})
//                kycDokumentLesen(n,id,{ip}) → {meta,daten} · kycDokumentLoeschen(n,id) · kycEinreichen(n,{ip}) · kycErneut(n)
//   Querschnitt: kycStatus(n|null,{kontoId|organisationId}) · kycFreigabePruefen(n,{schritt,kontoId,organisationId,flaecheId})
//   Compliance:  kycWarteschlange(n,{status,q}) · kycFallDetail(n,id,{ip}) · kycAktion(n,id,{aktion,…}) · kycEinstellungen(n)
//                kycEinstellungenSpeichern(n,daten) · kycSanktionsliste(n) · kycSanktionPruefen(n,{name,geburtsdatum,art}) · kycFristen(n,{stichtag})
//
// FÜR ANDERE TEAMS (serverseitig):
//   import { kycStatus, kycFreigabe } from "@/lib/plattform/backend/kyc";
//   const s = await kycStatus(nutzer);                      // bzw. kycStatus({ organisationId }) / kycStatus("U-26-…")
//   const f = await kycFreigabe("auszahlung", { kontoId, flaecheId });   // { ok, aktiv, gruende, hinweis }
//   Im Demo-Backend innerhalb einer Schreib-Transaktion: kycSperre(db, schritt, {kontoId,…}) aus backend/demo/kycRegeln.js.
//   Frappe: oekoinvest_app.plattform.kyc_kern.kyc_status(konto) bzw. kyc_sperre(schritt, konto_id=…, …).
//   Externe Prüfergebnisse: kycErgebnisAnhaengen(fallId|{kontoId}, { quelle, art, ergebnis, zusammenfassung, rohdatenRef })
//   bzw. im Demo-Transaktionskontext kycErgebnisAnhaengenDb(db, …); Frappe kyc_kern.ergebnis_anhaengen(fall_id, eintrag).
//
// Nur serverseitig verwenden.

import * as demo from "./demo/kyc";
import * as frappe from "./frappe/kyc";
import { backendName, KONFIG_FEHLER } from "./index";
import { PlattformFehler } from "../fehler";

export const KYC_OPERATIONEN = [
  "kycFall", "kycSpeichern", "kycDokumentSpeichern", "kycDokumentLesen", "kycDokumentLoeschen", "kycEinreichen", "kycErneut", "kycStatus",
  "kycFreigabePruefen", "kycWarteschlange", "kycFallDetail", "kycAktion", "kycEinstellungen", "kycEinstellungenSpeichern", "kycSanktionsliste",
  "kycSanktionPruefen", "kycFristen", "kycFreigabeSystem", "kycErgebnisAnhaengen",
];

if (process.env.NODE_ENV !== "production") {
  for (const [name, impl] of [["demo", demo], ["frappe", frappe]]) {
    const fehlt = KYC_OPERATIONEN.filter((op) => typeof impl[op] !== "function");
    if (fehlt.length) console.warn(`[plattform] KYC ${name}: fehlende Operationen ${fehlt.join(", ")}`);
  }
}

export function kycBackend() {
  const n = backendName();
  if (n === "frappe") return frappe;
  if (n === "demo") return demo;
  throw new PlattformFehler(503, KONFIG_FEHLER);
}

/**
 * KYC-Status eines Kontos oder einer Organisation (Systemaufruf ohne Nutzerkontext, nur serverseitig).
 * ziel: Nutzer-Objekt ({ id }) · Organisation ({ id, art } oder { organisationId }) · Kennung "U-…"/"O-…"
 * Liefert { status, verifiziert, kontotyp, fallId, bank: { vorhanden, geprueft }, eigentum: [flaecheIds], naechstePruefung, … }
 */
export async function kycStatus(ziel) {
  let kontoId = null;
  let organisationId = null;
  if (typeof ziel === "string") (ziel.startsWith("O-") ? (organisationId = ziel) : (kontoId = ziel));
  else if (ziel?.organisationId) organisationId = ziel.organisationId;
  else if (ziel?.rollen || ziel?.email) {
    kontoId = ziel.id;
    organisationId = ziel.organisation?.id || null;
  } else if (ziel?.id?.startsWith?.("O-")) organisationId = ziel.id;
  else kontoId = ziel?.id || null;
  return kycBackend().kycStatus(null, { kontoId, organisationId });
}

/**
 * Externes Prüfergebnis an einen KYC-Fall anhängen (für das Team „Dienste“: Identitätsanbieter, MRZ, Register, Bonität).
 * fall: "KY-…" oder { kontoId } / { organisationId }; eintrag: { quelle, art, ergebnis: ok|auffaellig|fehler|hinweis|ausstehend,
 * zusammenfassung, rohdatenRef?, externeId?, daten? }. Entscheidet nie selbst – die Compliance sieht es im Fall.
 */
export async function kycErgebnisAnhaengen(fall, eintrag) {
  return kycBackend().kycErgebnisAnhaengen(fall, eintrag);
}

/** Freigabe eines Schritts (Gating) als Systemaufruf: { ok, aktiv, gruende, hinweis } */
export async function kycFreigabe(schritt, { kontoId = null, organisationId = null, flaecheId = null } = {}) {
  return kycBackend().kycFreigabeSystem(schritt, { kontoId, organisationId, flaecheId });
}
// src/lib/plattform/backend/demo/speicher.js
//
// Datei-Datenbank des Demo-Backends: eine JSON-Datei unter .data/plattform.json
// (steht in .gitignore). Schreiben nur unter einer Sperrdatei (funktioniert auch,
// wenn Next.js das Modul mehrfach lädt) und atomar über Datei + Umbenennen.
// Uploads liegen unter .data/uploads/ mit zufälligen Dateinamen.

import { promises as fs, readFileSync, statSync } from "node:fs";
import path from "node:path";

export const DATEN_ORDNER = path.join(process.cwd(), ".data");
export const UPLOAD_ORDNER = path.join(DATEN_ORDNER, "uploads");
const DATEI = path.join(DATEN_ORDNER, "plattform.json");
const SPERRE = path.join(DATEN_ORDNER, "plattform.lock");
const SCHEMA = 2; // 2: Benachrichtigungen, Postausgang, Aufgaben, Checklisten

let cache = null; // { mtimeMs, size, db }

const warte = (ms) => new Promise((r) => setTimeout(r, ms));

async function sperren() {
  await fs.mkdir(DATEN_ORDNER, { recursive: true });
  const start = Date.now();
  for (;;) {
    try {
      const h = await fs.open(SPERRE, "wx");
      await h.writeFile(String(process.pid));
      await h.close();
      return;
    } catch (e) {
      if (e.code !== "EEXIST") throw e;
      // verwaiste Sperre (Prozess abgestürzt) nach 10 s entfernen
      try {
        const st = await fs.stat(SPERRE);
        if (Date.now() - st.mtimeMs > 10000) await fs.rm(SPERRE, { force: true });
      } catch {
        /* inzwischen weg */
      }
      if (Date.now() - start > 8000) throw new Error("Demo-Datenbank ist gesperrt");
      await warte(10 + Math.random() * 20);
    }
  }
}

async function entsperren() {
  await fs.rm(SPERRE, { force: true }).catch(() => {});
}

// BEWUSST SYNCHRON: React 19 schneidet im Dev-Modus den Rückgabewert von
// awaited I/O (fs.promises) für die Debug-Anzeige mit und liefert ihn im
// HTML aus – das war die komplette Demo-Datenbank inkl. Passwort-Hashes auf
// jeder Seite (2–5 MB). Synchrones Lesen erzeugt keinen solchen I/O-Eintrag.
async function dateiLesen() {
  try {
    const st = statSync(DATEI);
    if (cache && cache.mtimeMs === st.mtimeMs && cache.size === st.size) return structuredClone(cache.db);
    const roh = readFileSync(DATEI, "utf8");
    const db = JSON.parse(roh);
    cache = { mtimeMs: st.mtimeMs, size: st.size, db };
    return structuredClone(db);
  } catch (e) {
    if (e.code === "ENOENT") return null;
    throw e;
  }
}

async function dateiSchreiben(db) {
  const tmp = `${DATEI}.${process.pid}.${Date.now()}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(db, null, 1), "utf8");
  for (let i = 0; ; i++) {
    try {
      await fs.rename(tmp, DATEI);
      break;
    } catch (e) {
      // Windows: Ziel kurzzeitig von einem Leser geöffnet
      if (i > 20 || !["EPERM", "EBUSY", "EACCES"].includes(e.code)) {
        await fs.rm(tmp, { force: true }).catch(() => {});
        throw e;
      }
      await warte(15);

      await warte(15);
    }
  }
  cache = null;
}

let seedFn = null;
/** Seed-Funktion registrieren (liefert eine neue, befüllte Datenbank) */
export function seedSetzen(fn) {
  seedFn = fn;
}

async function sicherstellen() {
  const db = await dateiLesen();
  if (db && db.schema === SCHEMA) return db;
  await sperren();
  try {
    const erneut = await dateiLesen();
    if (erneut && erneut.schema === SCHEMA) return erneut;
    const neu = await seedFn();
    neu.schema = SCHEMA;
    await dateiSchreiben(neu);
    return structuredClone(neu);
  } finally {
    await entsperren();
  }
}

/** Nur lesen (Kopie – Änderungen daran werden NICHT gespeichert) */
export async function lesen() {
  return sicherstellen();
}

/** Lesen, ändern, speichern unter Sperre. `fn(db)` darf db verändern und ein Ergebnis liefern. */
export async function aendern(fn) {
  await sicherstellen();
  await sperren();
  try {
    const db = await dateiLesen();
    const ergebnis = await fn(db);
    await dateiSchreiben(db);
    return ergebnis;
  } finally {
    await entsperren();
  }
}

export async function uploadSchreiben(dateiname, daten) {
  await fs.mkdir(UPLOAD_ORDNER, { recursive: true });
  await fs.writeFile(path.join(UPLOAD_ORDNER, path.basename(dateiname)), daten);
}

export async function uploadLesen(dateiname) {
  return fs.readFile(path.join(UPLOAD_ORDNER, path.basename(dateiname)));
}

export async function uploadLoeschen(dateiname) {
  await fs.rm(path.join(UPLOAD_ORDNER, path.basename(dateiname)), { force: true });
}
