311	function letzterSonntagUtc(jahr, monat) {
312	  const d = new Date(Date.UTC(jahr, monat + 1, 0));
313	  return d.getUTCDate() - d.getUTCDay();
314	}
315	/** Beginn/Ende der Sommerzeit in UTC-ms (01:00 UTC am letzten Sonntag im März/Oktober) */
316	export function sommerzeitGrenzen(jahr) {
317	  return { beginn: Date.UTC(jahr, 2, letzterSonntagUtc(jahr, 2), 1), ende: Date.UTC(jahr, 9, letzterSonntagUtc(jahr, 9), 1) };
318	}
319	/** Versatz Ortszeit – UTC in Stunden für einen UTC-Zeitpunkt */
320	export function versatzH(ms) {
321	  const { beginn, ende } = sommerzeitGrenzen(new Date(ms).getUTCFullYear());
322	  return ms >= beginn && ms < ende ? 2 : 1;
323	}
324	/** Ortszeit-Bestandteile eines UTC-Zeitpunkts */
325	export function ortszeit(ms) {
326	  const d = new Date(ms + versatzH(ms) * 3600000);
327	  return { jahr: d.getUTCFullYear(), monat: d.getUTCMonth(), tag: d.getUTCDate(), stunde: d.getUTCHours(), minute: d.getUTCMinutes(), wochentag: (d.getUTCDay() + 6) % 7 /* 0 = Mo */, datum: d.toISOString().slice(0, 10) };
328	}
