330	/** Lokale Wandzeit → UTC. `zweite` = zweites Auftreten in der doppelten Oktober-Stunde. Liefert {ms, art} */
331	function ortszeitZuUtc(j, mo, t, h, mi, { zweite = false, nurMez = false } = {}) {
332	  const wand = Date.UTC(j, mo, t, h, mi);
333	  if (nurMez) return { ms: wand - 3600000, art: "normal" };
334	  const { beginn, ende } = sommerzeitGrenzen(j);
335	  // übersprungene Stunde im März: Wandzeit 02:00–02:59 existiert nicht
336	  const sprungVon = beginn + 3600000; // 02:00 MEZ-Wandzeit = beginn + 1 h
337	  if (wand >= sprungVon && wand < sprungVon + 3600000) return { ms: wand - 3600000, art: "luecke" };
338	  // doppelte Stunde im Oktober: Wandzeit 02:00–02:59 existiert zweimal
339	  const doppelVon = ende + 3600000; // 02:00 Wandzeit
340	  if (wand >= doppelVon && wand < doppelVon + 3600000) return { ms: wand - (zweite ? 3600000 : 7200000), art: "doppelt" };
341	  const sommer = wand - 7200000 >= beginn && wand - 7200000 < ende;
342	  return { ms: wand - (sommer ? 7200000 : 3600000), art: "normal" };
343	}
