347	const RE_DE = /^(\d{1,2})\.(\d{1,2})\.(\d{2}|\d{4})(?:[ T]+(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/;
348	const RE_ISO = /^(\d{4})-(\d{2})-(\d{2})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2})(?:\.\d+)?)?)?\s*(Z|[+-]\d{2}:?\d{2})?$/i;
349	const RE_ZEIT = /^(\d{1,2}):(\d{2})(?::(\d{2}))?$/;
350	
351	function datumLesen(s) {
352	  const x = s.trim().replace(/^"|"$/g, "");
353	  let m = RE_DE.exec(x);
354	  if (m) {
355	    const j = m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3]);
356	    return { j, mo: Number(m[2]) - 1, t: Number(m[1]), h: m[4] !== undefined ? Number(m[4]) : null, mi: m[5] !== undefined ? Number(m[5]) : null, offset: null };
357	  }
358	  m = RE_ISO.exec(x);
359	  if (m) {
360	    let offset = null;
361	    if (m[7]) offset = m[7].toUpperCase() === "Z" ? 0 : (m[7][0] === "-" ? -1 : 1) * (Number(m[7].slice(1, 3)) * 60 + Number(m[7].slice(-2)));
362	    return { j: Number(m[1]), mo: Number(m[2]) - 1, t: Number(m[3]), h: m[4] !== undefined ? Number(m[4]) : null, mi: m[5] !== undefined ? Number(m[5]) : null, offset };
363	  }
364	  return null;
365	}
366	function zeitLesen(s) {
367	  const m = RE_ZEIT.exec(s.trim().replace(/^"|"$/g, ""));
368	  return m ? { h: Number(m[1]), mi: Number(m[2]) } : null;
369	}
370	function zahlLesen(s) {
371	  let x = String(s).trim().replace(/^"|"$/g, "").replace(/\s/g, "");
372	  if (!x || !/^[+-]?[\d.,]+(e[+-]?\d+)?$/i.test(x)) return null;
373	  if (x.includes(",") && x.includes(".")) x = x.lastIndexOf(",") > x.lastIndexOf(".") ? x.replace(/\./g, "").replace(",", ".") : x.replace(/,/g, "");
374	  else if (x.includes(",")) x = x.replace(",", ".");
375	  const n = Number(x);
376	  return Number.isFinite(n) ? n : null;
377	}
