383	  if (/1[.-][45]\.\d|1-1:1\.[45]\b/.test(t)) return "kW";
384	  if (/\bmwh\b/.test(t)) return "MWh";
385	  if (/\bkwh\b/.test(t)) return "kWh";
386	  if (/(^|[^k])\bwh\b/.test(t)) return "Wh";
387	  if (/\bmw\b/.test(t)) return "MW";
388	  if (/\bkw\b/.test(t)) return "kW";
389	  if (/\[w\]|\(w\)|\bin w\b|\bwatt\b/.test(t)) return "W";
