395	function trennzeichen(zeilen) {
396	  const probe = zeilen.slice(0, 40).join("\n");
397	  const zaehl = (c) => probe.split(c).length - 1;
398	  const s = zaehl(";");
399	  const t = zaehl("\t");
400	  if (s >= Math.max(t, 1)) return ";";
401	  if (t >= 1) return "\t";
402	  return ",";
403	}
