405	function feldSplit(zeile, sep) {
406	  if (!zeile.includes('"')) return zeile.split(sep);
407	  const out = [];
408	  let akt = "";
409	  let inQ = false;
410	  for (const c of zeile) {
411	    if (c === '"') inQ = !inQ;
412	    else if (c === sep && !inQ) {
413	      out.push(akt);
414	      akt = "";
415	    } else akt += c;
416	  }
417	  out.push(akt);
418	  return out;
419	}
