430	  if (zeilen.length < 10) return { ok: false, fehler: "Die Datei enthält zu wenige Zeilen für einen Lastgang." };
431	  if (zeilen.length > MAX_ZEILEN) return { ok: false, fehler: `Die Datei ist zu groß (mehr als ${MAX_ZEILEN.toLocaleString("de-DE")} Zeilen). Bitte höchstens drei Jahre hochladen.` };
432	  const sep = trennzeichen(zeilen);
433	  const hinweise = [];
434	
435	  // Kopf- und Metadatenzeilen sammeln (alles vor der ersten Datenzeile)
