439	  for (let i = 0; i < Math.min(zeilen.length, 60); i++) {
440	    const f = feldSplit(zeilen[i], sep);
441	    if (datumLesen(f[0] || "") && f.slice(1).some((x) => zahlLesen(x) !== null)) {
442	      erste = i;
443	      break;
444	    }
