459	      spalte = 2;
460	      if (zeitLesen(probe[2] || "")) {
461	        endeSpalte = 2;
462	        spalte = 3;
463	      }
464	    } else return { ok: false, fehler: "Uhrzeit fehlt – erwartet wird ein Viertelstunden- oder Stundenwert je Zeile." };
465	  } else if (probe[1] && datumLesen(probe[1])?.h !== null && datumLesen(probe[1])) {
