476	    if (idx >= 0 && zahlLesen(probe[idx] ?? "") !== null) wertSpalte = idx;
477	  }
478	  if (wertSpalte < 0) wertSpalte = probe.findIndex((x, i) => i >= spalte && zahlLesen(x) !== null);
