488	    einheitQuelle = "vorgabe";
489	  }
490	  if (!einheit) {
491	    einheit = "kW";
492	    hinweise.push({ stufe: "warnung", text: "Einheit nicht erkannt – die Werte werden als Leistungsmittelwerte in kW gelesen. Wählen Sie sonst die Einheit aus (z. B. kWh je Viertelstunde)." });
