496	  // Zeilen lesen (Ortszeit oder mit Offset)
497	  const roheWerte = [];
498	  let fehlerZeilen = 0;
499	  for (let i = erste; i < zeilen.length; i++) {
500	    const f = feldSplit(zeilen[i], sep);
501	    const d = datumLesen(f[0] || "");
502	    const w = zahlLesen(f[wertSpalte] ?? "");
503	    if (!d || w === null) {
504	      fehlerZeilen++;
505	      continue;
506	    }
507	    let h = d.h;
508	    let mi = d.mi;
509	    if (zeitSpalte >= 0) {
510	      const z = zeitLesen(f[zeitSpalte] || "");
511	      if (!z) {
512	        fehlerZeilen++;
513	        continue;
514	      }
515	      h = z.h;
516	      mi = z.mi;
517	    }
518	    if (h === 24 && mi === 0) {
519	      // 24:00 = Intervallende am Tagesende
520	      const n = new Date(Date.UTC(d.j, d.mo, d.t + 1));
521	      roheWerte.push({ j: n.getUTCFullYear(), mo: n.getUTCMonth(), t: n.getUTCDate(), h: 0, mi: 0, offset: d.offset, w });
522	    } else roheWerte.push({ j: d.j, mo: d.mo, t: d.t, h, mi, offset: d.offset, w });
523	  }
524	  if (roheWerte.length < 96) return { ok: false, fehler: "Zu wenige gültige Messwerte (mindestens ein Tag in Viertelstunden)." };
