527	  // Zeitbasis: Datei mit Offsets → exakt; sonst MEZ/MESZ. Zeiten aus der übersprungenen März-Stunde → durchgehend MEZ.
528	  const mitOffset = roheWerte.every((r) => r.offset !== null);
529	  let nurMez = false;
530	  if (!mitOffset) {
531	    for (const r of roheWerte) {
532	      const { art } = ortszeitZuUtc(r.j, r.mo, r.t, r.h, r.mi);
533	      if (art === "luecke") {
534	        nurMez = true;
535	        break;
536	      }
537	    }
538	  }
539	
540	  // Intervall erkennen (Median der Abstände der Wandzeiten)
541	  const wand = roheWerte.slice(0, 2000).map((r) => Date.UTC(r.j, r.mo, r.t, r.h, r.mi));
