598	        dstTage.add(new Date(beginn).toISOString().slice(0, 10));
599	      }
600	    }
601	  }
602	  const start = Math.floor(punkte[0].ms / SLOT_MS) * SLOT_MS;
603	  const ende = Math.floor(punkte[punkte.length - 1].ms / SLOT_MS) * SLOT_MS + intervallMs;
604	  const n = Math.round((ende - start) / SLOT_MS);
605	  if (n > 3 * 366 * 96 + 96) return { ok: false, fehler: "Zeitraum länger als drei Jahre – bitte kürzen." };
606	  const kw = new Array(n).fill(NaN);
607	  let doppelt = 0;
608	  const jeSlot = intervallMin / 15;
609	  for (const p of punkte) {
610	    const i0 = Math.round((p.ms - start) / SLOT_MS);
611	    for (let k = 0; k < jeSlot; k++) {
612	      const i = i0 + k;
613	      if (i < 0 || i >= n) continue;
614	      if (!Number.isNaN(kw[i])) {
615	        if (k === 0) doppelt++;
616	        continue;
617	      }
618	      kw[i] = p.kw;
619	    }
620	  }
621	
622	  // Plausibilisierung
623	  const gueltig = kw.filter((x) => !Number.isNaN(x));
624	  const luecken = n - gueltig.length;
625	  const negativ = gueltig.filter((x) => x < 0).length;
626	  const sortiert = [...gueltig].sort((a, b) => a - b);
627	  const med = sortiert[Math.floor(sortiert.length / 2)] || 0;
628	  const ausreisser = med > 0 ? gueltig.filter((x) => x > med * 25).length : 0;
629	  let nullLauf = 0;
630	  let maxNull = 0;
631	  for (const x of kw) {
632	    if (x === 0) maxNull = Math.max(maxNull, ++nullLauf);
633	    else nullLauf = 0;
634	  }
635	  if (luecken) hinweise.push({ stufe: luecken > n * 0.02 ? "warnung" : "info", text: `${luecken.toLocaleString("de-DE")} Viertelstunden fehlen (${((luecken / n) * 100).toLocaleString("de-DE", { maximumFractionDigits: 1 })} %) – sie werden in der Analyse nicht mitgerechnet, der Jahresverbrauch wird hochgerechnet.` });
636	  if (doppelt) hinweise.push({ stufe: "warnung", text: `${doppelt} doppelte Zeitstempel außerhalb der Zeitumstellung – jeweils der erste Wert wurde verwendet.` });
637	  if (negativ) hinweise.push({ stufe: "warnung", text: `${negativ} negative Werte – enthält die Datei Einspeisung? Für den Reststrom zählt nur der Bezug.` });
638	  if (ausreisser) hinweise.push({ stufe: "warnung", text: `${ausreisser} Werte über dem 25-Fachen des Medians – Einheit (W statt kW?) oder Messfehler prüfen.` });
639	  if (maxNull >= 96 * 3) hinweise.push({ stufe: "info", text: `Längste Phase ohne Verbrauch: ${Math.round(maxNull / 96)} Tage (Betriebsruhe oder Messausfall?).` });
640	  if (nurMez) hinweise.push({ stufe: "info", text: "Die Datei ist durchgehend in Winterzeit (MEZ) geführt – so wurde gerechnet." });
641	  if (mitOffset) hinweise.push({ stufe: "info", text: "Zeitstempel mit Zeitzonenangabe erkannt – exakte Zuordnung ohne Zeitumstellungsregel." });
642	  else if (!nurMez && dstTage.size) hinweise.push({ stufe: "info", text: `Zeitumstellung berücksichtigt (${[...dstTage].sort().map((t) => t.split("-").reverse().join(".")).join(", ")}).` });
643	
644	  return {
645	    ok: true,
646	    startMs: start,
647	    n,
648	    kw,
649	    intervallMin,
650	    einheit,
651	    einheitQuelle,
652	    zeitbasis: mitOffset ? "offset" : nurMez ? "mez" : "mez_mesz",
653	    hinweise,
654	    statistik: { zeilen: roheWerte.length, fehlerZeilen, luecken, doppelt, dstDoppelt, dstLuecke, negativ, ausreisser, maxNullTage: Math.round(maxNull / 96) },
655	  };
656	}
