660	const REGION_GEO = { "de-nord": [53.6, 10], "de-ost": [51.8, 12.5], "de-west": [50.7, 7.5], "de-sued": [48.4, 10.9], at: [47.9, 13.8], ch: [47.2, 8.0] };
661	const profilCache = new Map();
662	/** Sonnenstandsprofil eines UTC-Tages (96 Gewichte, Summe 1) – wie im Anlagen-Simulator */
663	function sonnenprofil(regionId, doy) {
664	  const k = `${regionId}|${doy}`;
665	  if (profilCache.has(k)) return profilCache.get(k);
666	  const [lat, lon] = REGION_GEO[regionId] || REGION_GEO["de-sued"];
667	  const phi = (lat * Math.PI) / 180;
668	  const dekl = ((23.44 * Math.PI) / 180) * Math.sin((2 * Math.PI * (284 + doy)) / 365);
669	  const w = new Float64Array(96);
670	  let s = 0;
671	  for (let i = 0; i < 96; i++) {
672	    const utcH = (i + 0.5) * 0.25;
673	    const ha = ((utcH + lon / 15 - 12) * 15 * Math.PI) / 180;
674	    const sinEl = Math.sin(phi) * Math.sin(dekl) + Math.cos(phi) * Math.cos(dekl) * Math.cos(ha);
675	    w[i] = sinEl > 0.02 ? sinEl : 0; // Dach/Gewerbe: breites Profil
676	    s += w[i];
677	  }
678	  if (s > 0) for (let i = 0; i < 96; i++) w[i] /= s;
679	  profilCache.set(k, w);
680	  return w;
681	}
