683	/** PV-Leistung (kW) je Viertelstunde für das Raster eines Lastgangs; spezErtrag in kWh/kWp·a */
684	export function pvReihe(startMs, n, kwp, { regionId = "de-sued", spezErtrag } = {}) {
685	  const region = REGIONEN.find((r) => r.id === regionId) || REGIONEN[3];
686	  const jahr = kwp * (spezErtrag || Math.round(region.ertrag * 0.9)); // Gewerbedach: ~ 90 % des Freiflächen-Richtwerts
687	  const out = new Float64Array(n);
688	  for (let i = 0; i < n; i++) {
689	    const ms = startMs + i * SLOT_MS;
690	    const d = new Date(ms);
691	    const tag0 = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
692	    const doy = Math.floor((tag0 - Date.UTC(d.getUTCFullYear(), 0, 1)) / TAG_MS) + 1;
693	    const tageMonat = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
694	    const tagKwh = (jahr * (ALLGEMEIN.pvMonatsanteile?.[d.getUTCMonth()] ?? 1 / 12)) / tageMonat;
695	    const slot = Math.floor((ms - tag0) / SLOT_MS);
696	    out[i] = Math.min(kwp * 0.85, (tagKwh * sonnenprofil(regionId, doy)[slot]) / 0.25);
697	  }
698	  return out;
699	}
