703	function quantil(sortiert, q) {
704	  if (!sortiert.length) return 0;
705	  const i = Math.min(sortiert.length - 1, Math.max(0, Math.round(q * (sortiert.length - 1))));
706	  return sortiert[i];
707	}
708	const rund = (x, s = 0) => Math.round(x * 10 ** s) / 10 ** s;
