710	/**
711	 * Analyse eines geparsten Lastgangs.
712	 * @param {object} g Ergebnis von lastgangParsen (ok)
713	 * @param {{regionId?, pvKwp?, bestandPvKwp?, preisCt?, produzierend?}} o
714	 */
715	export function lastgangAnalyse(g, { regionId = "de-sued", pvKwp = null, bestandPvKwp = 0, preisCt = 20, produzierend = false } = {}) {
716	  const { kw, startMs, n } = g;
717	  const woche = Array.from({ length: 7 }, () => new Array(24).fill(0));
718	  const wocheN = Array.from({ length: 7 }, () => new Array(24).fill(0));
719	  const monate = new Array(12).fill(0);
720	  const monateN = new Array(12).fill(0);
721	  let summeKwh = 0;
722	  let gueltig = 0;
723	  let spitze = -Infinity;
724	  let spitzeMs = startMs;
725	  let solarKwh = 0;
726	  let wochenendeKwh = 0;
727	  let mittagSumme = 0;
728	  let mittagN = 0;
729	  const werte = [];
730	  for (let i = 0; i < n; i++) {
731	    const x = kw[i];
732	    if (Number.isNaN(x)) continue;
733	    const v = Math.max(0, x);
734	    const ms = startMs + i * SLOT_MS;
735	    const o = ortszeit(ms);
736	    gueltig++;
737	    summeKwh += v / 4;
738	    werte.push(v);
739	    if (v > spitze) {
740	      spitze = v;
741	      spitzeMs = ms;
742	    }
743	    woche[o.wochentag][o.stunde] += v;
744	    wochenN_add(wocheN, o.wochentag, o.stunde);
745	    monate[o.monat] += v / 4;
746	    monateN[o.monat]++;
747	    if (o.stunde >= 8 && o.stunde < 17) solarKwh += v / 4;
748	    if (o.wochentag >= 5) wochenendeKwh += v / 4;
749	    if (o.wochentag < 5 && o.stunde >= 11 && o.stunde < 14) {
750	      mittagSumme += v;
751	      mittagN++;
752	    }
753	  }
754	  const tageAbgedeckt = gueltig / 96;
755	  const faktorJahr = tageAbgedeckt > 0 ? 365 / tageAbgedeckt : 0;
756	  const jahresKwh = summeKwh * faktorJahr;
757	  werte.sort((a, b) => a - b);
758	  const grundlast = quantil(werte, 0.05);
759	  const benutzungsstunden = spitze > 0 ? jahresKwh / spitze : 0;
760	  const tagAnteil = summeKwh > 0 ? solarKwh / summeKwh : 0;
761	  const mittagslast = mittagN ? mittagSumme / mittagN : 0;
762	  const profil = LASTPROFILE.reduce((best, p) => (Math.abs(p.tag - tagAnteil) < Math.abs(best.tag - tagAnteil) ? p : best), LASTPROFILE[0]);
763	  const lastdauer = Array.from({ length: 21 }, (_, k) => rund(quantil(werte, 1 - k / 20), 1));
764	
765	  // PV-Deckungspotenzial: Varianten je Anlagengröße (Vielfache der Mittagslast) plus gewünschte Größe
766	  const basis = Math.max(10, mittagslast);
767	  const groessen = [...new Set([0.5, 1, 1.5, 2].map((f) => Math.max(10, Math.round((basis * f) / 10) * 10)).concat(pvKwp > 0 ? [Math.round(pvKwp)] : []))].sort((a, b) => a - b);
768	  const pv = groessen.map((kwp) => {
769	    const reihe = pvReihe(startMs, n, kwp, { regionId });
770	    let erzeugt = 0;
771	    let ev = 0;
772	    for (let i = 0; i < n; i++) {
773	      if (Number.isNaN(kw[i])) continue;
774	      erzeugt += reihe[i] / 4;
775	      ev += Math.min(reihe[i], Math.max(0, kw[i])) / 4;
776	    }
777	    erzeugt *= faktorJahr;
778	    ev *= faktorJahr;
779	    return { kwp, erzeugungKwh: Math.round(erzeugt), eigenverbrauchKwh: Math.round(ev), evQuote: erzeugt > 0 ? rund(ev / erzeugt, 3) : 0, autarkie: jahresKwh > 0 ? rund(ev / jahresKwh, 3) : 0 };
780	  });
781	  // Empfehlung: größte Variante mit Eigenverbrauchsquote ≥ 70 %
782	  const empfehlung = [...pv].reverse().find((x) => x.evQuote >= 0.7) || pv[0];
783	  const gewaehlt = pvKwp > 0 ? pv.find((x) => x.kwp === Math.round(pvKwp)) : empfehlung;
784	
785	  // Pool-Ersparnis auf den Reststrom (nach der gewählten bzw. empfohlenen PV)
786	  const reststromKwh = Math.max(0, jahresKwh - (gewaehlt?.eigenverbrauchKwh || 0));
787	  const pool = berechneReststrom({ verbrauchMwh: reststromKwh / 1000, preisCt, profil: profil.id, pvKwp: 0, pvBestand: true, produzierend });
788	
789	  return {
790	    zeitraum: { von: new Date(startMs).toISOString(), bis: new Date(startMs + n * SLOT_MS).toISOString(), tage: rund(tageAbgedeckt, 1), hochgerechnet: tageAbgedeckt < 360, abdeckung: rund(gueltig / n, 3) },
791	    verbrauchKwh: Math.round(summeKwh),
792	    jahresverbrauchKwh: Math.round(jahresKwh),
793	    spitzeKw: rund(spitze, 1),
794	    spitzeAm: new Date(spitzeMs).toISOString(),
795	    spitzeOrtszeit: (() => {
796	      const o = ortszeit(spitzeMs);
797	      return `${o.datum.split("-").reverse().join(".")} ${String(o.stunde).padStart(2, "0")}:${String(o.minute).padStart(2, "0")}`;
798	    })(),
799	    benutzungsstunden: Math.round(benutzungsstunden),
800	    grundlastKw: rund(grundlast, 1),
801	    mittagslastKw: rund(mittagslast, 1),
802	    mittelKw: rund(gueltig ? (summeKwh * 4) / gueltig : 0, 1),
803	    tagAnteil: rund(tagAnteil, 3),
804	    wochenendeAnteil: rund(summeKwh ? wochenendeKwh / summeKwh : 0, 3),
805	    lastprofil: { id: profil.id, label: profil.label },
806	    wochenprofil: woche.map((r, t) => r.map((s, h) => rund(wocheN[t][h] ? s / wocheN[t][h] : 0, 1))),
807	    monate: monate.map((m, i) => ({ monat: i + 1, kwh: Math.round(m), vollstaendig: monateN[i] >= 26 * 96 })),
808	    lastdauerlinie: lastdauer,
809	    pv: { varianten: pv, empfehlungKwp: empfehlung?.kwp || null, gewaehltKwp: gewaehlt?.kwp || null, regionId, bestandKwp: bestandPvKwp || 0 },
810	    pool: {
811	      reststromKwh: Math.round(reststromKwh),
812	      preisCt,
813	      ersparnisEurMin: Math.round(pool.gesamt.eurMin),
814	      ersparnisEurMax: Math.round(pool.gesamt.eurMax),
815	      ctMin: rund(pool.gesamt.ctMin, 2),
816	      ctMax: rund(pool.gesamt.ctMax, 2),
817	      stromsteuerEur: pool.stromsteuer ? Math.round(pool.stromsteuer.eur) : null,
818	      preisUnplausibel: pool.preisUnplausibel,
819	      klein: pool.klein,
820	    },
821	  };
822	}
823	function wochenN_add(m, t, h) {
824	  m[t][h]++;
825	}
