// src/lib/energy.js
//
// Live-Daten zum deutschen Strommarkt – nur öffentliche, schlüsselfreie Quellen:
//   - Fraunhofer ISE Energy-Charts (CC BY 4.0): Day-Ahead-Preis DE-LU in
//     15-Minuten-Auflösung und öffentliche Nettostromerzeugung je Quelle.
//     https://api.energy-charts.info
//   - aWATTar (Fallback für die Preise): stündlicher Day-Ahead-Preis.
//
// Alle Abrufe laufen serverseitig mit Next-Cache (revalidate), damit Besucher
// nie direkt die Drittanbieter treffen und die Seite schnell bleibt.

const EC = "https://api.energy-charts.info";

// Umsatzsteuer & typische Netzentgelte/Umlagen – für die Einordnung
// "was kostet eine kWh mit dynamischem Tarif ungefähr". Bewusst als
// Orientierung gekennzeichnet.
export const TARIF_ANNAHMEN = {
  aufschlagCt: 19.5, // Netzentgelt, Abgaben, Umlagen, Marge (netto, ct/kWh) – grobe Orientierung 2026
  mwst: 0.19,
  festpreisCt: 36, // durchschnittlicher Haushalts-Festpreis in ct/kWh brutto (Orientierung)
};

async function holeJson(url, revalidate) {
  const res = await fetch(url, {
    next: { revalidate },
    headers: { Accept: "application/json", "User-Agent": "oekoinvest energy widget" },
  });
  if (!res.ok) throw new Error(`${url} -> ${res.status}`);
  return res.json();
}

/** Tagesbeginn (lokal Europe/Berlin) als ISO-Datum YYYY-MM-DD */
function berlinDatum(offsetTage = 0) {
  const d = new Date(Date.now() + offsetTage * 86400000);
  return new Intl.DateTimeFormat("sv-SE", { timeZone: "Europe/Berlin" }).format(d);
}

/**
 * Day-Ahead-Preise für heute (und morgen, falls schon veröffentlicht – ab ca. 13 Uhr).
 * Rückgabe: [{ t: ms, eurMwh }]
 */
export async function getSpotPrices() {
  try {
    const start = berlinDatum(0);
    const ende = berlinDatum(2);
    const j = await holeJson(`${EC}/price?bzn=DE-LU&start=${start}&end=${ende}`, 900);
    const punkte = (j.unix_seconds || [])
      .map((s, i) => ({ t: s * 1000, eurMwh: j.price?.[i] }))
      .filter((p) => typeof p.eurMwh === "number");
    if (punkte.length) return { quelle: "Energy-Charts (Fraunhofer ISE)", aufloesungMin: 15, punkte };
  } catch (e) {
    console.error("energy-charts price:", e.message);
  }
  try {
    const j = await holeJson("https://api.awattar.de/v1/marketdata", 900);
    const punkte = (j.data || []).map((p) => ({ t: p.start_timestamp, eurMwh: p.marketprice }));
    return { quelle: "aWATTar", aufloesungMin: 60, punkte };
  } catch (e) {
    console.error("awattar:", e.message);
    return { quelle: null, aufloesungMin: 60, punkte: [] };
  }
}

/**
 * Stromerzeugung nach Quelle (Energy-Charts public_power) ab gestern 0 Uhr bis jetzt.
 * Gestern ist mit dabei, damit Diagramme auch kurz nach Mitternacht einen
 * vollständigen 24-Stunden-Verlauf zeigen können. Die Kennzahlen im Snapshot
 * nutzen weiterhin den jüngsten Wert (idx).
 */
export async function getGeneration() {
  try {
    const j = await holeJson(`${EC}/public_power?country=de&start=${berlinDatum(-1)}&end=${berlinDatum(1)}`, 900);
    const zeiten = (j.unix_seconds || []).map((s) => s * 1000);
    const reihe = (name) => j.production_types?.find((p) => p.name === name)?.data || [];
    const summe = (...namen) =>
      zeiten.map((_, i) => namen.reduce((acc, n) => acc + (Number(reihe(n)[i]) || 0), 0));

    const serien = {
      solar: reihe("Solar"),
      windOnshore: reihe("Wind onshore"),
      windOffshore: reihe("Wind offshore"),
      biomasse: reihe("Biomass"),
      wasser: summe("Hydro Run-of-River", "Hydro water reservoir"),
      braunkohle: reihe("Fossil brown coal / lignite"),
      steinkohle: reihe("Fossil hard coal"),
      gas: reihe("Fossil gas"),
      // Rest der öffentlichen Nettoerzeugung (Müll, Öl, Grubengas, Geothermie, Pumpspeicher, Sonstige)
      sonstige: summe("Waste", "Fossil oil", "Fossil coal-derived gas", "Geothermal", "Others", "Hydro pumped storage"),
      last: reihe("Load"),
      eeAnteil: reihe("Renewable share of load"),
    };

    // Letzter Zeitpunkt mit Solar- UND Lastwert
    let idx = -1;
    for (let i = zeiten.length - 1; i >= 0; i--) {
      if (serien.solar[i] != null && serien.last[i] != null) { idx = i; break; }
    }
    return { quelle: "Energy-Charts (Fraunhofer ISE)", zeiten, serien, idx };
  } catch (e) {
    console.error("energy-charts power:", e.message);
    return { quelle: null, zeiten: [], serien: {}, idx: -1 };
  }
}

/** Kompakte Live-Zusammenfassung für Ticker, Widgets und Dashboard. */
export async function getEnergySnapshot() {
  const [preise, erzeugung] = await Promise.all([getSpotPrices(), getGeneration()]);
  const jetzt = Date.now();
  const schritt = preise.aufloesungMin * 60000;

  const heuteStr = berlinDatum(0);
  const tagVon = (t) => new Intl.DateTimeFormat("sv-SE", { timeZone: "Europe/Berlin" }).format(new Date(t));
  const heute = preise.punkte.filter((p) => tagVon(p.t) === heuteStr);
  const morgen = preise.punkte.filter((p) => tagVon(p.t) === berlinDatum(1));
  const aktuell = preise.punkte.find((p) => p.t <= jetzt && jetzt < p.t + schritt) || null;

  const stat = (arr) => {
    if (!arr.length) return null;
    const werte = arr.map((p) => p.eurMwh);
    const min = arr.reduce((a, b) => (b.eurMwh < a.eurMwh ? b : a));
    const max = arr.reduce((a, b) => (b.eurMwh > a.eurMwh ? b : a));
    return { avg: werte.reduce((a, b) => a + b, 0) / werte.length, min, max, negativ: werte.filter((w) => w < 0).length };
  };

  const { serien, idx, zeiten } = erzeugung;
  const wert = (s) => (idx >= 0 && serien[s] ? Number(serien[s][idx]) || 0 : null);
  const wind = idx >= 0 ? (wert("windOnshore") || 0) + (wert("windOffshore") || 0) : null;

  return {
    stand: new Date().toISOString(),
    preis: {
      quelle: preise.quelle,
      aufloesungMin: preise.aufloesungMin,
      aktuell,
      heute: stat(heute),
      morgen: stat(morgen),
      punkte: preise.punkte,
    },
    erzeugung: {
      quelle: erzeugung.quelle,
      zeitpunkt: idx >= 0 ? zeiten[idx] : null,
      solarMw: wert("solar"),
      windMw: wind,
      lastMw: wert("last"),
      eeAnteil: wert("eeAnteil"),
      solarAnteil: idx >= 0 && wert("last") ? (wert("solar") / wert("last")) * 100 : null,
      zeiten,
      serien,
    },
  };
}

/** €/MWh (Börse, netto) -> ct/kWh */
export const ctKwh = (eurMwh) => eurMwh / 10;

/** Grobe Brutto-Endkundenkosten bei dynamischem Tarif in ct/kWh. */
export const dynamischBrutto = (eurMwh) => (ctKwh(eurMwh) + TARIF_ANNAHMEN.aufschlagCt) * (1 + TARIF_ANNAHMEN.mwst);

// src/lib/rechner/reststrom.js
//
// Reststrom-Rechner: Was kann der Pool (Bündelung, Solar-PPA, Flexibilität)
// beim Strom sparen, den ein Unternehmen trotz eigener PV noch aus dem Netz
// bezieht? Reine Funktionen ohne React – im Browser UND in Node testbar:
//
//   node src/lib/rechner/reststrom.js      → Selbsttest
//
// Alle Marktwerte kommen aus src/lib/invest/markt.js (STROM, REGIONEN).
// Ergebnis ist eine Spanne zur Orientierung, kein Angebot.

import { STROM, REGIONEN } from "../invest/markt.js";

/**
 * Lastprofile. `tag` = Anteil des Verbrauchs in den Solarstunden (ca. 8–17 Uhr),
 * `ppa`/`flex` = Faktoren auf die Hebel-Spannen aus STROM.poolHebel,
 * `eigenverbrauch` = typische Eigenverbrauchsquote einer eigenen PV-Anlage.
 * Eigene, vorsichtige Einschätzung auf Basis typischer Gewerbe-Lastgänge.
 */
export const LASTPROFILE = [
  { id: "einschicht", label: "Einschicht", sub: "ca. 6–16 Uhr", tag: 0.62, ppa: 1.0, flex: 0.8, eigenverbrauch: 0.7 },
  { id: "zweischicht", label: "Zweischicht", sub: "ca. 6–22 Uhr", tag: 0.5, ppa: 0.85, flex: 1.0, eigenverbrauch: 0.8 },
  { id: "dreischicht", label: "Dreischicht", sub: "rund um die Uhr", tag: 0.38, ppa: 0.65, flex: 0.75, eigenverbrauch: 0.9 },
  { id: "handel", label: "Handel & Büro", sub: "Laden, Kühlung, Klima", tag: 0.55, ppa: 0.9, flex: 0.9, eigenverbrauch: 0.75 },
];

export const profilById = (id) => LASTPROFILE.find((p) => p.id === id) || LASTPROFILE[0];

/** Mittlerer spezifischer Ertrag einer Gewerbe-PV (Dach, nicht optimal ausgerichtet) – Mittel der DE-Regionen × 0,9 */
const DE_REGIONEN = REGIONEN.filter((r) => r.land === "DE");
export const PV_ERTRAG_KWH_PRO_KWP = Math.round((DE_REGIONEN.reduce((s, r) => s + r.ertrag, 0) / DE_REGIONEN.length) * 0.9);

/** Ab dieser Menge ist ein Pool-Beitritt in der Regel sinnvoll (MWh/Jahr) – vorsichtige Orientierung */
export const SINNVOLL_AB_MWH = 100;

/** Die Beschaffung lässt sich nicht beliebig drücken: max. Anteil der Beschaffungskomponente, der eingespart werden kann */
const MAX_ANTEIL_BESCHAFFUNG = 0.35;

const fixeBestandteile = () => STROM.bestandteile.filter((b) => !b.beeinflussbar);
const stromsteuerRegel = () => STROM.bestandteile.find((b) => b.id === "stromsteuer")?.ct ?? 0;

/**
 * @param {object} e
 * @param {number} e.verbrauchMwh     Jahresverbrauch aus dem Netz heute (MWh)
 * @param {number} e.preisCt          aktueller Arbeitspreis gesamt, netto (ct/kWh)
 * @param {string} e.profil           id aus LASTPROFILE
 * @param {number} e.pvKwp            eigene PV-Leistung (0 = keine)
 * @param {boolean} e.pvBestand       true: PV läuft schon (Verbrauch oben ist bereits Reststrom)
 * @param {boolean} e.produzierend    produzierendes Gewerbe / Land- und Forstwirtschaft
 */
export function berechneReststrom({ verbrauchMwh = 500, preisCt = 20, profil = "einschicht", pvKwp = 0, pvBestand = false, produzierend = false } = {}) {
  const p = profilById(profil);
  const verbrauchKwh = Math.max(0, verbrauchMwh) * 1000;

  // 1) Eigene PV: Eigenverbrauch deckt einen Teil der Tagesstunden
  const pvErtrag = Math.max(0, pvKwp) * PV_ERTRAG_KWH_PRO_KWP;
  const tagesLast = verbrauchKwh * p.tag;
  // Geplante PV: Eigenverbrauch höchstens 90 % der Tageslast
  const eigenverbrauch = pvBestand ? 0 : Math.min(pvErtrag * p.eigenverbrauch, tagesLast * 0.9);
  const reststromKwh = Math.max(0, verbrauchKwh - eigenverbrauch);
  // Wie stark sind die Tagesstunden schon durch eigene PV gedeckt? (bestimmt den PPA-Spielraum)
  const pvDeckungTag = tagesLast > 0 ? Math.min(1, (pvErtrag * p.eigenverbrauch) / tagesLast) : 0;

  // 2) Preiszerlegung heute
  const fix = fixeBestandteile().map((b) => ({ ...b }));
  const fixSumme = fix.reduce((s, b) => s + b.ct, 0);
  const beschaffungVorher = Math.max(0, preisCt - fixSumme);
  const preisUnplausibel = preisCt < fixSumme + 3;

  // 3) Hebel des Pools in ct/kWh Reststrom
  const faktor = {
    buendelung: 1,
    ppa: p.ppa * Math.max(0.25, 1 - pvDeckungTag),
    flex: p.flex * (pvKwp > 0 ? 1.1 : 1),
  };
  let hebel = STROM.poolHebel.map((h) => {
    const f = faktor[h.id] ?? 1;
    return { id: h.id, label: h.label, ctMin: h.ct.min * f, ctMax: h.ct.max * f };
  });

  // Deckel: nie mehr als MAX_ANTEIL_BESCHAFFUNG der heutigen Beschaffungskomponente
  const deckel = beschaffungVorher * MAX_ANTEIL_BESCHAFFUNG;
  const summeMax = hebel.reduce((s, h) => s + h.ctMax, 0);
  if (summeMax > deckel) {
    // proportional kürzen – Verhältnis der Hebel bleibt erhalten
    const k = summeMax > 0 ? deckel / summeMax : 0;
    hebel = hebel.map((h) => ({ ...h, ctMin: h.ctMin * k, ctMax: h.ctMax * k }));
  }
  hebel = hebel.map((h) => ({ ...h, eurMin: (h.ctMin / 100) * reststromKwh, eurMax: (h.ctMax / 100) * reststromKwh }));

  const gesamt = {
    ctMin: hebel.reduce((s, h) => s + h.ctMin, 0),
    ctMax: hebel.reduce((s, h) => s + h.ctMax, 0),
  };
  gesamt.ctMitte = (gesamt.ctMin + gesamt.ctMax) / 2;
  gesamt.eurMin = (gesamt.ctMin / 100) * reststromKwh;
  gesamt.eurMax = (gesamt.ctMax / 100) * reststromKwh;
  gesamt.eurMitte = (gesamt.eurMin + gesamt.eurMax) / 2;

  const kostenVorher = (preisCt / 100) * reststromKwh;
  gesamt.anteilMin = kostenVorher > 0 ? gesamt.eurMin / kostenVorher : 0;
  gesamt.anteilMax = kostenVorher > 0 ? gesamt.eurMax / kostenVorher : 0;

  // 4) Preiszerlegung vorher/nachher (nachher mit Mitte der Spanne)
  const vorher = [{ id: "beschaffung", label: "Beschaffung & Vertrieb", ct: beschaffungVorher, beeinflussbar: true }, ...fix];
  const nachher = [{ id: "beschaffung", label: "Beschaffung & Vertrieb (Pool)", ct: Math.max(0, beschaffungVorher - gesamt.ctMitte), beeinflussbar: true }, ...fix];

  // 5) Stromsteuer-Entlastung (separat, keine Pool-Leistung – Antrag beim Hauptzollamt)
  const steuerDiff = stromsteuerRegel() - STROM.stromsteuerProduzierend;
  const stromsteuer = produzierend
    ? { ctJeKwh: steuerDiff, eur: (steuerDiff / 100) * reststromKwh }
    : null;

  return {
    profil: p,
    verbrauchKwh,
    pvErtrag,
    eigenverbrauch,
    reststromKwh,
    pvDeckungTag,
    fixSumme,
    beschaffungVorher,
    preisUnplausibel,
    kostenVorher,
    hebel,
    gesamt,
    vorher,
    nachher,
    stromsteuer,
    klein: verbrauchMwh < SINNVOLL_AB_MWH,
  };
}

