def _einladung_suchen(token):
	import re

	if not re.match(r"^[A-Za-z0-9_-]{20,200}$", str(token or "")):
		return None
	name = frappe.db.get_value(LE, {"token_hash": sha256(token)}, "name")
	return frappe.get_doc(LE, name) if name else None


